attributes.initialValue:
z.object({
  parser: z.object({
    include: z.array(z.string()).default(['**/*.{ts,tsx,js,jsx,ets}']),
    exclude: z.array(z.string()).default(['node_modules/**', 'dist/**', 'build/**', '.git/**']),
    maxFileSize: z.number().int().default(1024 * 1024) // 1MB
  }).default({}),
  graph: z.object({
    dataDir: z.string().default('./.arkts-code-graph'),
    persistToDisk: z.boolean().default(true)
  }).default({}),
  vector: z.object({
    enabled: z.boolean().default(true),
    dimension: z.number().int().default(1536),
    similarityThreshold: z.number().default(0.7)
  }).default({}),
  logging: z.object({
    level: z.enum(['trace', 'debug', 'info', 'warn', 'error', 'fatal']).default('info'),
    prettyPrint: z.boolean().default(true),
    file: z.string().optional()
  }).default({})
}).default({})
